 static GameObject Place(string n,string asset,Transform parent,Vector3 pos,float yaw=0,bool collide=false,Vector3 size=default(Vector3)){var src=AssetDatabase.LoadAssetAtPath<GameObject>(asset);if(!src)throw new Exception("Missing "+asset);var g=(GameObject)PrefabUtility.InstantiatePrefab(src,parent);g.name=n;g.transform.localPosition=pos;g.transform.localRotation=Quaternion.Euler(0,yaw,0);foreach(var c in g.GetComponentsInChildren<Collider>(true))UnityEngine.Object.DestroyImmediate(c);foreach(var l in g.GetComponentsInChildren<Light>(true))UnityEngine.Object.DestroyImmediate(l);foreach(var mr in g.GetComponentsInChildren<Renderer>())mr.sharedMaterials=mr.sharedMaterials.Select(m=>m&&mats.TryGetValue(m.name,out var v)?v:m).ToArray();if(collide)foreach(var mf in g.GetComponentsInChildren<MeshFilter>())mf.gameObject.AddComponent<MeshCollider>().sharedMesh=mf.sharedMesh;if(size!=Vector3.zero){var bc=g.AddComponent<BoxCollider>();bc.size=size;bc.center=Vector3.up*size.y/2;}PrefabUtility.RecordPrefabInstancePropertyModifications(g.transform);placements.Add(new{name=n,asset,position=new[]{pos.x,pos.y,pos.z},yaw});return g;}
